// === Tab: mySketch ===
// For the #WCCChallenge, theme: "creature".
// Creature film data culled from IMDB and other sources.
// https://www.imdb.com/list/ls066923786/
// https://en.wikipedia.org/wiki/Clapperboard
// A clapperboard, also known as a dumb slate, clapboard, film clapper, film slate, 
// bertolo clapz, movie slate, or production slate, is a device used in filmmaking, 
// television production and video production to assist in synchronizing of picture 
// and sound, and to designate and mark the various scenes and takes 
// as they are filmed and audio-recorded. 

var ease;
var t = 0;
var ang = 0;
var tang = 0;
var take = 1;
var pos, tpos;
var scene = 1;
var roll = 1;
var mode = 0;
var title, ryear, rmo, rday, director;
var findex = -1;

function preload() {
	snap = loadSound('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png');
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/rocksalt.ttf');
	films = loadTable('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/movies.csv');
	rolling = loadSound('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/film.mp3');
}

function setup() {
	createCanvas(windowHeight * 0.95, windowHeight * 0.95);
	rectMode(CENTER);
	ang = 0;
	ease = new p5.Ease();
	pos = createVector(-width / 2, 33 * height / 48);
	tpos = createVector(-width / 2, 33 * height / 48);
	tang = -PI / 6;
	pickFilm();
}

function draw() {
	pos.lerp(tpos, 0.3);
	t += 0.15;
	let q = ease['quinticIn'](t);
	ang = map(q, 0.0, 1.0, ang, tang, true);
	background(0);
	fill(random(10,30));
	if (rolling.isPlaying()) rect(width / 2, height / 2, width, height, height/30);
	fill(200)
	textFont('arial');
	textSize(height / 16);
	if (pos.x < -width / 2.1) text('CLICK!', width / 2, height / 2);
	noStroke();
	translate(pos);
	scale(height / 600)
	push();
	fill(0);
	rect(0, 0, 400, 300, 0, 0, 5, 5);
	push();
	translate(0, -130);
	fill(15);
	rect(0, 0, 410, 40, 0, 0, 5, 5)
	for (let x = -100; x < 200; x += 50) {
		fill('white');
		push();
		shearX(-PI / 4);
		rect(x, 0, 25, 40)
		pop();
	}
	pop();
	translate(-200, -150);
	rotate(ang);
	translate(200, -20);
	fill(15);
	rect(0, 0, 410, 40, 5, 5, 0, 0);
	for (let x = -100; x < 200; x += 50) {
		fill('white');
		push();
		shearX(PI / 4);
		rect(x, 0, 25, 40);
		pop();
	}
	pop();
	push();
	translate(-200, -150);
	fill(20);
	ellipse(0, 0, 25);
	fill(255);
	ellipse(0, 0, 10);
	fill(0);
	ellipse(0, 0, 5)
	pop();
	stroke(255);
	strokeWeight(2);
	line(-190, -60, 190, -60);
	line(-190, 20, 190, 20);
	line(-190, 70, 190, 70);
	line(-190, 120, 190, 120);
	line(-100, -60, -100, 20);
	line(0, -60, 0, 20);
	line(100, -60, 100, 20);
	noStroke();
	fill(255);
	textSize(12);
	textAlign(LEFT, BOTTOM);
	textFont('arial')
	text('PRODUCTION', -190, -95);
	text('DIRECTOR', -190, 38);
	textAlign(LEFT, TOP);
	text('ROLL', -190, -55);
	text('SCENE', -95, -55);
	text('TAKE', 5, -55);
	text('FPS', 105, -55);
	text('DATE', -190, 75);
	fill(255, 180);
	textFont(font);
	textAlign(CENTER, CENTER);
	textSize(22)
	text(take, 50, -25);
	text(scene, -50, -25);
	text(roll, -150, -25);
	text(24, 150, -25);
	text(director, 0, 40);
	text(ryear, 0, 85);
	textSize(min(22, 500 / title.length));
	text(title, 0, -90);
}

function mousePressed() {
	if (!rolling.isPlaying() && frameCount>10 && mode==1) {
		started = true;
		rolling.setVolume(0.2)
		rolling.play();
	}
	if(rolling.isPlaying() && mode==0) rolling.stop();
	mode = (mode + 1) % 3;
	switch (mode) {
		case 0:
			retractSlate();
			break;
		case 1:
			tpos.x = width / 2;
			break;
		case 2:
			clapSlate();
			break;
	}
}

function clapSlate() {
	tang = 0;
	snap.setVolume(1);
	snap.play();
	t = 0;
}

function retractSlate() {
	tpos.x = -width / 2;
	tang = random(-PI/4,-PI / 6);
	t = 0;
	if (frameCount > 30) take += 1;
	if (take > 9) {
		scene += 1;
		take = 1;
	}
	if (scene % 3 == 0 && take == 1) {
		roll += 1;
	}
	pickFilm()
}

function pickFilm() {
	findex = (findex+1)%films.getRowCount();
	title = films.getString(findex, 0);
	ryear = films.getString(findex, 1);
	director = films.getString(findex, 2);
}
